alter table schedule_solve_jobs add column if not exists budget_ms integer not null default 30000,add column if not exists deadline_at timestamptz,add column if not exists base_seed integer,add column if not exists cancel_reason text;
alter table schedule_solve_attempts add column if not exists result_fingerprint text,add column if not exists audit_status text,add column if not exists accepted_at timestamptz;
do $$begin if not exists(select 1 from pg_constraint where conname='schedule_solve_attempts_audit_status_check') then alter table schedule_solve_attempts add constraint schedule_solve_attempts_audit_status_check check(audit_status is null or audit_status in('PENDING','ACCEPTED','REJECTED','DUPLICATE','LATE'));end if;end$$;
create index if not exists idx_schedule_solve_attempts_job_audit on schedule_solve_attempts(job_id,audit_status,status);
create index if not exists idx_schedule_solve_attempts_lease on schedule_solve_attempts(status,lease_until) where status='RUNNING';

create or replace function get_schedule_compute_capabilities_v2() returns table(worker_key text,display_name text,worker_type text,health text,max_parallel smallint,current_load numeric,avg_latency_ms integer,lease_seconds integer,heartbeat_fresh boolean,available_slots integer,load_ratio numeric,recommended boolean) language sql stable security definer set search_path=public as $$select w.worker_key,w.display_name,w.worker_type,w.health,w.max_parallel,w.current_load,w.avg_latency_ms,w.lease_seconds,(w.worker_key='db-native' or(w.last_heartbeat is not null and w.last_heartbeat>now()-make_interval(secs=>greatest(w.lease_seconds*2,60)))),greatest(0,w.max_parallel-ceil(greatest(0,w.current_load)*w.max_parallel)::int),least(1,greatest(0,w.current_load)),(w.active and w.health in('HEALTHY','DEGRADED') and(w.worker_key='db-native' or(w.last_heartbeat is not null and w.last_heartbeat>now()-make_interval(secs=>greatest(w.lease_seconds*2,60)))) and greatest(0,w.max_parallel-ceil(greatest(0,w.current_load)*w.max_parallel)::int)>0) from schedule_compute_workers w where w.active order by case w.health when 'HEALTHY' then 0 when 'DEGRADED' then 1 else 2 end,least(1,greatest(0,w.current_load)),coalesce(w.avg_latency_ms,2147483647),w.priority$$;

create or replace function plan_schedule_solve_job_v2(p_mode text default 'ADVANCED',p_candidate_count smallint default 4,p_compute_preference text default 'AUTO',p_quality_target smallint default 75,p_budget_ms integer default 30000,p_base_seed integer default null) returns uuid language plpgsql security definer set search_path=public as $$declare j uuid;ids uuid[];i int;w uuid;cfg jsonb;seed0 int;begin perform open_permission_context('schedule.generate');if p_candidate_count<1 or p_candidate_count>32 then raise exception 'candidate_count 1..32 olmalıdır';end if;if p_compute_preference not in('AUTO','DB','CPU','GPU','HYBRID') then raise exception 'COMPUTE_PREFERENCE_INVALID';end if;if p_budget_ms<5000 or p_budget_ms>300000 then raise exception 'BUDGET_MS_INVALID';end if;seed0:=coalesce(p_base_seed,((extract(epoch from clock_timestamp())*1000)::bigint%2147483647)::int);cfg:=jsonb_build_object('lns',jsonb_build_object('enabled',upper(p_mode)='ADVANCED','policy','BLOCK_AWARE_V1','preserve_locked',true,'preserve_blocks',true),'hybrid',jsonb_build_object('authority','V2','budget_ms',p_budget_ms,'base_seed',seed0));insert into schedule_solve_jobs(mode,candidate_count,compute_preference,quality_target,status,config,budget_ms,deadline_at,base_seed) values(p_mode,p_candidate_count,p_compute_preference,p_quality_target,'QUEUED',cfg,p_budget_ms,now()+make_interval(secs=>ceil(p_budget_ms/1000.0)::int),seed0) returning id into j;select array_agg(id order by case worker_type when 'GPU' then 0 when 'CPU' then 1 else 2 end,least(1,greatest(0,current_load)),coalesce(avg_latency_ms,2147483647),priority) into ids from schedule_compute_workers where active and health in('HEALTHY','DEGRADED') and(worker_key='db-native' or(last_heartbeat is not null and last_heartbeat>now()-make_interval(secs=>greatest(lease_seconds*2,60)))) and(p_compute_preference in('AUTO','HYBRID') or worker_type=p_compute_preference) and(worker_key='db-native' or greatest(0,max_parallel-ceil(greatest(0,current_load)*max_parallel)::int)>0);if coalesce(array_length(ids,1),0)=0 then select array_agg(id) into ids from schedule_compute_workers where worker_key='db-native' and active;end if;if coalesce(array_length(ids,1),0)=0 then raise exception 'NO_COMPUTE_WORKER';end if;for i in 1..p_candidate_count loop w:=ids[((i-1)%array_length(ids,1))+1];insert into schedule_solve_attempts(job_id,worker_id,attempt_no,seed,status,profile_key) values(j,w,i,(seed0+i*7919)::int,'PLANNED','HYBRID_V2');end loop;return j;end$$;

create or replace function get_schedule_solve_job_status_v2(p_job_id uuid) returns table(job_status text,deadline_at timestamptz,budget_ms integer,attempt_id uuid,attempt_no smallint,worker_key text,worker_type text,attempt_status text,audit_status text,duration_ms integer,scenario_id uuid,finished_at timestamptz) language sql stable security definer set search_path=public as $$select j.status,j.deadline_at,j.budget_ms,a.id,a.attempt_no,w.worker_key,w.worker_type,a.status,a.audit_status,a.duration_ms,a.scenario_id,a.finished_at from schedule_solve_jobs j join schedule_solve_attempts a on a.job_id=j.id left join schedule_compute_workers w on w.id=a.worker_id where j.id=p_job_id and j.institution_code=current_tenant_code() order by a.attempt_no$$;

create or replace function cancel_schedule_solve_job_v2(p_job_id uuid,p_reason text default 'CLIENT_TIMEOUT') returns integer language plpgsql security definer set search_path=public as $$declare n int;begin perform open_permission_context('schedule.generate');if not exists(select 1 from schedule_solve_jobs where id=p_job_id and institution_code=current_tenant_code()) then raise exception 'JOB_NOT_FOUND';end if;update schedule_solve_attempts set status='CANCELLED',finished_at=coalesce(finished_at,now()),lease_until=null,diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('cancel_reason',coalesce(p_reason,'CANCELLED'),'cancelled_at',now()) where job_id=p_job_id and status in('PLANNED','RUNNING');get diagnostics n=row_count;update schedule_solve_jobs set status='CANCELLED',finished_at=now(),cancel_reason=coalesce(p_reason,'CANCELLED') where id=p_job_id and status in('QUEUED','RUNNING','PARTIAL');return n;end$$;

create or replace function reap_stale_schedule_worker_attempts_v2() returns integer language plpgsql security definer set search_path=public as $$declare r record;n int:=0;nw uuid;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;for r in select a.id,a.job_id,a.worker_id,j.deadline_at,w.worker_type,w.worker_key from schedule_solve_attempts a join schedule_solve_jobs j on j.id=a.job_id join schedule_compute_workers w on w.id=a.worker_id where a.status='RUNNING' and(j.deadline_at<=now() or a.lease_until is null or a.lease_until<=now() or(w.worker_key<>'db-native' and(w.last_heartbeat is null or w.last_heartbeat<=now()-make_interval(secs=>greatest(w.lease_seconds*2,60))))) for update of a skip locked loop if r.deadline_at<=now() then update schedule_solve_attempts set status='CANCELLED',audit_status='LATE',finished_at=coalesce(finished_at,now()),lease_until=null,diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('budget_expired_at',now()) where id=r.id;else select x.id into nw from schedule_compute_workers x where x.active and x.id<>r.worker_id and x.worker_type in('CPU','GPU') and x.health in('HEALTHY','DEGRADED') and x.last_heartbeat>now()-make_interval(secs=>greatest(x.lease_seconds*2,60)) and greatest(0,x.max_parallel-(select count(*) from schedule_solve_attempts z where z.worker_id=x.id and z.status='RUNNING'))>0 order by case when x.worker_type=r.worker_type then 0 when r.worker_type='GPU' and x.worker_type='CPU' then 1 else 2 end,greatest(0,x.current_load),coalesce(x.avg_latency_ms,2147483647),x.priority limit 1;if nw is not null then update schedule_solve_attempts set worker_id=nw,status='PLANNED',started_at=null,claimed_at=null,lease_until=null,diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('reaped_from',r.worker_key,'reaped_at',now()) where id=r.id;else update schedule_solve_attempts set status='FAILED',finished_at=now(),lease_until=null,diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('stale_worker',r.worker_key,'failed_at',now()) where id=r.id;end if;end if;n:=n+1;end loop;update schedule_solve_jobs j set status=case when exists(select 1 from schedule_solve_attempts a where a.job_id=j.id and a.audit_status='ACCEPTED') then 'COMPLETED' when exists(select 1 from schedule_solve_attempts a where a.job_id=j.id and a.status='COMPLETED') then 'PARTIAL' when j.deadline_at<=now() then 'CANCELLED' else 'FAILED' end,finished_at=now() where j.status in('QUEUED','RUNNING','PARTIAL') and not exists(select 1 from schedule_solve_attempts a where a.job_id=j.id and a.status in('PLANNED','RUNNING'));return n;end$$;

create or replace function heartbeat_schedule_worker_attempt_v2(p_worker_key text,p_attempt_id uuid,p_current_load numeric default null,p_avg_latency_ms integer default null) returns boolean language plpgsql security definer set search_path=public as $$declare w schedule_compute_workers%rowtype;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;select * into w from schedule_compute_workers where worker_key=p_worker_key and active and worker_type in('CPU','GPU');if not found then raise exception 'WORKER_NOT_FOUND';end if;update schedule_solve_attempts a set lease_until=least(j.deadline_at,now()+make_interval(secs=>w.lease_seconds)) from schedule_solve_jobs j where a.id=p_attempt_id and a.job_id=j.id and a.worker_id=w.id and a.status='RUNNING' and j.deadline_at>now();if not found then raise exception 'ATTEMPT_NOT_OWNED_OR_EXPIRED';end if;update schedule_compute_workers set current_load=coalesce(p_current_load,current_load),avg_latency_ms=coalesce(p_avg_latency_ms,avg_latency_ms),health='HEALTHY',last_heartbeat=now(),updated_at=now() where id=w.id;return true;end$$;

create or replace function worker_claim_schedule_attempt_v2(p_worker_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare w schedule_compute_workers%rowtype;a schedule_solve_attempts%rowtype;j schedule_solve_jobs%rowtype;payload jsonb;running_n int;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;perform reap_stale_schedule_worker_attempts_v2();select * into w from schedule_compute_workers where worker_key=p_worker_key and active and worker_type in('CPU','GPU') and health in('HEALTHY','DEGRADED') and last_heartbeat>now()-make_interval(secs=>greatest(lease_seconds*2,60)) for update;if not found then return null;end if;select count(*) into running_n from schedule_solve_attempts where worker_id=w.id and status='RUNNING';if running_n>=w.max_parallel then return null;end if;select a0.* into a from schedule_solve_attempts a0 join schedule_solve_jobs j0 on j0.id=a0.job_id where a0.worker_id=w.id and a0.status='PLANNED' and j0.status in('QUEUED','RUNNING') and j0.deadline_at>now() order by j0.created_at,a0.attempt_no for update of a0 skip locked limit 1;if not found then update schedule_compute_workers set last_heartbeat=now(),current_load=least(1,running_n::numeric/greatest(w.max_parallel,1)),updated_at=now() where id=w.id;return null;end if;select * into j from schedule_solve_jobs where id=a.job_id;update schedule_solve_attempts set status='RUNNING',claimed_at=now(),started_at=coalesce(started_at,now()),lease_until=least(j.deadline_at,now()+make_interval(secs=>w.lease_seconds)),audit_status=null where id=a.id;update schedule_solve_jobs set status='RUNNING',started_at=coalesce(started_at,now()) where id=j.id;update schedule_compute_workers set last_heartbeat=now(),current_load=least(1,(running_n+1)::numeric/greatest(w.max_parallel,1)),updated_at=now() where id=w.id;select jsonb_build_object('attempt_id',a.id,'job_id',j.id,'tenant',j.institution_code,'seed',a.seed,'quality_target',j.quality_target,'deadline_at',j.deadline_at,'budget_ms',j.budget_ms,'config',j.config,'problem',jsonb_build_object('time_profile',(select to_jsonb(t) from schedule_time_profiles t where t.institution_code=j.institution_code and t.active order by t.updated_at desc limit 1),'assignments',(select coalesce(jsonb_agg(jsonb_build_object('assignment_id',ta.id,'teacher_id',ta.teacher_id,'assigned_hours',ta.assigned_hours,'requirement_id',r.id,'class_id',r.class_id,'course_id',r.course_id,'weekly_hours',r.weekly_hours,'class_name',c.class_name,'course_name',cc.name,'week_pattern',ta.week_pattern,'valid_from',ta.valid_from,'valid_to',ta.valid_to,'term_no',ta.term_no,'schedule_session_id',coalesce(ta.schedule_session_id,c.schedule_session_id),'allowed_periods',case when exists(select 1 from schedule_period_definitions d where d.session_id=coalesce(ta.schedule_session_id,c.schedule_session_id) and d.active and d.institution_code=j.institution_code) then array(select d.period from schedule_period_definitions d where d.session_id=coalesce(ta.schedule_session_id,c.schedule_session_id) and d.active and d.institution_code=j.institution_code order by d.period) else array(select generate_series(1,(select periods_per_day from schedule_time_profiles tp where tp.institution_code=j.institution_code and tp.active order by tp.updated_at desc limit 1))::smallint) end)),'[]'::jsonb) from teacher_course_assignments ta join class_course_requirements r on r.id=ta.class_course_requirement_id join school_classes c on c.id=r.class_id join course_catalog cc on cc.id=r.course_id where ta.institution_code=j.institution_code),'locked_rows',(select coalesce(jsonb_agg(to_jsonb(ts)),'[]'::jsonb) from teacher_schedule ts where ts.institution_code=j.institution_code and ts.active and ts.locked),'teacher_unavailability',(select coalesce(jsonb_agg(to_jsonb(u)),'[]'::jsonb) from teacher_unavailability u where u.institution_code=j.institution_code and u.active),'teacher_constraints',(select coalesce(jsonb_agg(to_jsonb(tc)),'[]'::jsonb) from teacher_schedule_constraints tc where tc.institution_code=j.institution_code),'course_rules',(select coalesce(jsonb_agg(to_jsonb(cr)),'[]'::jsonb) from course_schedule_rules cr where cr.institution_code=j.institution_code and cr.active),'planning_relations',(select coalesce(jsonb_agg(to_jsonb(pr)),'[]'::jsonb) from schedule_planning_relations pr where pr.institution_code=j.institution_code and pr.active),'student_conflict_weights',(with e as(select e.student_id,e.teacher_assignment_id,r.course_id,coalesce(req.importance,1::numeric) importance,coalesce(req.allow_overlap,false) allow_overlap from student_schedule_enrollments e join teacher_course_assignments ta on ta.id=e.teacher_assignment_id join class_course_requirements r on r.id=ta.class_course_requirement_id left join lateral(select bool_or(scr.allow_overlap) allow_overlap,max((case upper(scr.request_kind) when 'PRIMARY' then 4 when 'ALTERNATIVE' then 2 when 'SUBSTITUTE' then 1 else 1 end)::numeric/greatest(scr.priority,1)) importance from student_course_requests scr where scr.active and scr.student_id=e.student_id and scr.course_id=r.course_id and scr.institution_code=j.institution_code) req on true where e.active and e.institution_code=j.institution_code),pairs as(select least(x.teacher_assignment_id,y.teacher_assignment_id) l,greatest(x.teacher_assignment_id,y.teacher_assignment_id) r,count(distinct x.student_id)::bigint students,sum(least(x.importance,y.importance))::numeric severity from e x join e y on y.student_id=x.student_id and x.teacher_assignment_id<y.teacher_assignment_id where not x.allow_overlap and not y.allow_overlap group by 1,2) select coalesce(jsonb_agg(jsonb_build_object('left_assignment_id',l,'right_assignment_id',r,'student_weight',students,'severity_weight',severity)),'[]'::jsonb) from pairs where students>0),'overrides',(select coalesce(jsonb_agg(to_jsonb(o)),'[]'::jsonb) from schedule_rule_overrides o where o.institution_code=j.institution_code and o.active))) into payload;return payload;end$$;

create or replace function worker_complete_schedule_attempt_v2(p_worker_key text,p_attempt_id uuid,p_result jsonb default null,p_duration_ms integer default null,p_error text default null,p_diagnostics jsonb default '{}'::jsonb) returns boolean language plpgsql security definer set search_path=public as $$declare w schedule_compute_workers%rowtype;j schedule_solve_jobs%rowtype;a schedule_solve_attempts%rowtype;fp text;dup uuid;running_n int;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;select * into w from schedule_compute_workers where worker_key=p_worker_key and active;if not found then raise exception 'WORKER_NOT_FOUND';end if;select x.* into a from schedule_solve_attempts x where x.id=p_attempt_id and x.worker_id=w.id and x.status='RUNNING' for update;if not found then raise exception 'ATTEMPT_NOT_OWNED';end if;select * into j from schedule_solve_jobs where id=a.job_id;if j.deadline_at<=now() or a.lease_until is null or a.lease_until<now() then update schedule_solve_attempts set status='CANCELLED',audit_status='LATE',finished_at=now(),lease_until=null,diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('late_submit_at',now()) where id=a.id;return false;end if;if p_error is not null then update schedule_solve_attempts set status='FAILED',finished_at=now(),lease_until=null,duration_ms=p_duration_ms,diagnostics=coalesce(diagnostics,'{}')||coalesce(p_diagnostics,'{}')||jsonb_build_object('error',p_error) where id=a.id;else if p_result is null or jsonb_typeof(p_result->'rows')<>'array' or jsonb_array_length(p_result->'rows')=0 then raise exception 'WORKER_RESULT_ROWS_REQUIRED';end if;fp:=md5((p_result->'rows')::text);select id into dup from schedule_solve_attempts where job_id=a.job_id and id<>a.id and result_fingerprint=fp and status='COMPLETED' order by finished_at nulls last limit 1;update schedule_solve_attempts set status='COMPLETED',audit_status=case when dup is null then 'PENDING' else 'DUPLICATE' end,result_payload=p_result,result_fingerprint=fp,duration_ms=p_duration_ms,diagnostics=coalesce(diagnostics,'{}')||coalesce(p_diagnostics,'{}')||case when dup is null then '{}'::jsonb else jsonb_build_object('duplicate_of',dup) end,finished_at=now(),lease_until=null where id=a.id;end if;select count(*) into running_n from schedule_solve_attempts where worker_id=w.id and status='RUNNING';update schedule_compute_workers set current_load=least(1,running_n::numeric/greatest(max_parallel,1)),last_heartbeat=now(),updated_at=now() where id=w.id;if not exists(select 1 from schedule_solve_attempts where job_id=a.job_id and status in('PLANNED','RUNNING')) then update schedule_solve_jobs set status=case when exists(select 1 from schedule_solve_attempts where job_id=a.job_id and audit_status='ACCEPTED') then 'COMPLETED' when exists(select 1 from schedule_solve_attempts where job_id=a.job_id and status='COMPLETED') then 'PARTIAL' else 'FAILED' end,finished_at=now() where id=a.job_id;end if;return true;end$$;

create or replace function accept_schedule_worker_result_v2(p_attempt_id uuid) returns uuid language plpgsql security definer set search_path=public as $$declare a schedule_solve_attempts%rowtype;j schedule_solve_jobs%rowtype;sid uuid;dup_sid uuid;ok boolean;h int;u int;r int;begin perform open_permission_context('schedule.generate');select * into a from schedule_solve_attempts where id=p_attempt_id for update;if not found then raise exception 'ATTEMPT_NOT_FOUND';end if;select * into j from schedule_solve_jobs where id=a.job_id;if j.institution_code<>current_tenant_code() then raise exception 'TENANT_MISMATCH';end if;if a.audit_status='ACCEPTED' and a.scenario_id is not null then return a.scenario_id;end if;if a.audit_status='DUPLICATE' then select scenario_id into dup_sid from schedule_solve_attempts where job_id=a.job_id and result_fingerprint=a.result_fingerprint and audit_status='ACCEPTED' and scenario_id is not null order by accepted_at limit 1;if dup_sid is not null then update schedule_solve_attempts set scenario_id=dup_sid,accepted_at=now() where id=a.id;return dup_sid;end if;return null;end if;if a.status<>'COMPLETED' or a.audit_status is distinct from 'PENDING' then return null;end if;if a.finished_at is null or a.finished_at>j.deadline_at then update schedule_solve_attempts set audit_status='LATE',diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('audit','LATE') where id=a.id;return null;end if;select scenario_id into dup_sid from schedule_solve_attempts where job_id=a.job_id and id<>a.id and result_fingerprint=a.result_fingerprint and audit_status='ACCEPTED' and scenario_id is not null limit 1;if dup_sid is not null then update schedule_solve_attempts set audit_status='DUPLICATE',scenario_id=dup_sid,accepted_at=now(),diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('audit','DUPLICATE') where id=a.id;return dup_sid;end if;begin sid:=import_local_schedule_candidate_v1(a.result_payload->'rows','Hybrid Worker Adayı');select applicable,hard_issue_count,unplaced_count,room_issue_count into ok,h,u,r from schedule_scenario_status_v2 where scenario_id=sid;if coalesce(ok,false) and coalesce(h,0)=0 and coalesce(u,0)=0 and coalesce(r,0)=0 then update schedule_solve_attempts set audit_status='ACCEPTED',scenario_id=sid,score=(select score from schedule_scenarios where id=sid),hard_issue_count=h,unplaced_count=u,accepted_at=now(),diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('canonical_audit','PASS','room_issue_count',r) where id=a.id;update schedule_solve_jobs set status=case when not exists(select 1 from schedule_solve_attempts x where x.job_id=a.job_id and x.status in('PLANNED','RUNNING')) then 'COMPLETED' else 'RUNNING' end,finished_at=case when not exists(select 1 from schedule_solve_attempts x where x.job_id=a.job_id and x.status in('PLANNED','RUNNING')) then now() else null end where id=a.job_id;return sid;else update schedule_solve_attempts set audit_status='REJECTED',scenario_id=sid,hard_issue_count=coalesce(h,0),unplaced_count=coalesce(u,0),diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('canonical_audit','REJECTED','hard_issue_count',coalesce(h,0),'unplaced_count',coalesce(u,0),'room_issue_count',coalesce(r,0)) where id=a.id;return null;end if;exception when others then update schedule_solve_attempts set audit_status='REJECTED',diagnostics=coalesce(diagnostics,'{}')||jsonb_build_object('canonical_audit','ERROR','message',sqlerrm) where id=a.id;return null;end;end$$;

create or replace function get_schedule_hybrid_health_v2() returns table(metric text,value bigint,detail text) language sql stable security definer set search_path=public as $$select 'FRESH_EXTERNAL_WORKERS',count(*)::bigint,'Heartbeat fresh ve boş slotu bulunan harici CPU/GPU' from get_schedule_compute_capabilities_v2() where worker_type<>'DB' and recommended union all select 'ACTIVE_JOBS',count(*)::bigint,'Tenant için aktif hybrid job' from schedule_solve_jobs where institution_code=current_tenant_code() and status in('QUEUED','RUNNING','PARTIAL') union all select 'PENDING_AUDIT',count(*)::bigint,'Canonical server audit bekleyen worker sonucu' from schedule_solve_attempts a join schedule_solve_jobs j on j.id=a.job_id where j.institution_code=current_tenant_code() and a.audit_status='PENDING' union all select 'ACCEPTED_TODAY',count(*)::bigint,'Bugün canonical audit geçen worker sonucu' from schedule_solve_attempts a join schedule_solve_jobs j on j.id=a.job_id where j.institution_code=current_tenant_code() and a.audit_status='ACCEPTED' and a.accepted_at>=current_date union all select 'REJECTED_OR_LATE_TODAY',count(*)::bigint,'Bugün rejected/late/duplicate worker sonucu' from schedule_solve_attempts a join schedule_solve_jobs j on j.id=a.job_id where j.institution_code=current_tenant_code() and a.audit_status in('REJECTED','LATE','DUPLICATE') and coalesce(a.finished_at,now())>=current_date$$;
